const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json.body || item.json;
  const ticketNum = data.ticket_number || 'N/A';
  const title = data.title || 'Untitled Issue';
  const label = data.suggested_label || 'unlabeled';
  const conf = data.label_confidence ? (data.label_confidence * 100).toFixed(0) + '%' : 'N/A';
  const pNotPlanned = data.p_not_planned !== undefined ? (data.p_not_planned * 100).toFixed(1) + '%' : 'N/A';
  const isComplete = data.is_complete !== undefined ? data.is_complete : true;
  const missing = Array.isArray(data.missing_info) ? data.missing_info.join(', ') : (data.missing_info || 'None');
  const p50 = data.predicted_time_to_close ? data.predicted_time_to_close.p50_days : '3.5';
  const p90 = data.predicted_time_to_close ? data.predicted_time_to_close.p90_days : '14.0';

  const isHighRisk = (data.p_not_planned && data.p_not_planned >= 0.35) || !isComplete || (parseFloat(p90) >= 30.0);
  const severityTag = isHighRisk ? '🚨 [HIGH PRIORITY]' : 'ℹ️ [TRIAGE UPDATE]';

  let alertMsg = `${severityTag} *Issue #${ticketNum}*

`;
  alertMsg += `• *Title*: \`${title.substring(0, 75)}\`
`;
  alertMsg += `• *Suggested Integration*: \`${label}\` (Confidence: ${conf})
`;
  alertMsg += `• *Not-Planned Risk*: *${pNotPlanned}*
`;
  alertMsg += `• *Resolution Forecast*: P50: *${p50} days* | P90: *${p90} days*
`;
  alertMsg += `• *Status*: ${isComplete ? '✅ Complete Report' : '⚠️ *Incomplete Report*'}
`;

  if (!isComplete) {
    alertMsg += `• *Missing Diagnostic Info*: ${missing}
`;
  }

  results.push({
    json: {
      ticket_number: ticketNum,
      is_high_risk: isHighRisk,
      message_text: alertMsg,
      issue_url: `https://github.com/home-assistant/core/issues/${ticketNum}`,
      raw_data: data
    }
  });
}

return results;
